<h1>账号中枢管理</h1><nav class="actions"><a href="#members">用户</a><a href="#clients">应用接入</a><a href="#settings">服务配置</a></nav><section class="card" id="members"><h2>用户</h2><form method="get"><input name="q" value="<?= $e($q) ?>" placeholder="账号或邮箱"><button>搜索</button></form><div class="table"><table><tr><th>用户</th><th>邮箱</th><th>状态</th><th>操作</th></tr><?php foreach($members as $m): ?><tr><td><?= $e($m['display_name']) ?><small><?= $e($m['username']) ?></small></td><td><?= $e($m['email']??'—') ?></td><td><?= $m['enabled']?'正常':'禁用' ?></td><td><?php if($m['role']!=='admin'): ?><form method="post" action="/admin/user"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= $e($m['id']) ?>"><input type="hidden" name="enabled" value="<?= $m['enabled']?'0':'1' ?>"><button class="secondary"><?= $m['enabled']?'禁用':'启用' ?></button></form><?php endif ?></td></tr><?php endforeach ?></table></div><p><a href="?page=<?= max(1,$page-1) ?>&amp;q=<?= $e(urlencode($q)) ?>">上一页</a> · <?= $page ?> · <a href="?page=<?= $page+1 ?>&amp;q=<?= $e(urlencode($q)) ?>">下一页</a></p></section>
<section class="card" id="clients"><h2>应用接入</h2><p>授权码 + PKCE S256。保存应用会撤销其旧凭证，每行一个完整回调地址。</p><?php $clients[]=['id'=>'','name'=>'','redirect_uris'=>'[]','logout_uris'=>'[]','confidential'=>1,'enabled'=>1];foreach($clients as $c): ?><details><summary><?= $e($c['id']?$c['name'].' · '.$c['id']:'＋ 新建应用') ?></summary><form method="post" action="/admin/client"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><label>应用 ID<input name="id" value="<?= $e($c['id']) ?>" <?= $c['id']?'readonly':'' ?> required></label><label>名称<input name="name" value="<?= $e($c['name']) ?>" required></label><label>登录回调<textarea name="redirect_uris" required><?= $e(implode("\n",json_decode($c['redirect_uris'],true))) ?></textarea></label><label>退出回调<textarea name="logout_uris"><?= $e(implode("\n",json_decode($c['logout_uris'],true))) ?></textarea></label><label>类型<select name="confidential"><option value="1" <?= $c['confidential']?'selected':'' ?>>服务端应用（密钥）</option><option value="0" <?= !$c['confidential']?'selected':'' ?>>公共客户端（无密钥）</option></select></label><label class="check"><input type="checkbox" name="enabled" value="1" <?= $c['enabled']?'checked':'' ?>>启用</label><label class="check"><input type="checkbox" name="rotate" value="1">重新生成密钥</label><button>保存应用</button></form></details><?php endforeach ?></section>
<section id="settings" class="grid two"><article class="card"><h2>微信小程序</h2><form method="post" action="/admin/settings"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="kind" value="wechat"><label>AppID<input name="app_id" value="<?= $e($wx['app_id']??'wx4ec45155a93041cc') ?>" required></label><label>AppSecret<input name="secret" type="password" autocomplete="new-password" placeholder="留空保留已配置密钥"></label><label>页面路径<input name="page" value="<?= $e($wx['page']??'pages/account-confirm/index') ?>" required></label><label>版本<select name="env"><?php foreach(['release'=>'正式版','trial'=>'体验版','develop'=>'开发版'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($wx['env']??'release')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label class="check"><input type="checkbox" name="enabled" value="1" <?= !empty($wx['enabled'])?'checked':'' ?>>启用微信扫码</label><button>保存微信配置</button></form></article><article class="card"><h2>邮箱验证码</h2><form method="post" action="/admin/settings"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="kind" value="smtp"><label>SMTP 主机<input name="host" value="<?= $e($smtp['host']??'') ?>" required></label><label>端口<input name="port" type="number" value="<?= $e($smtp['port']??587) ?>" required></label><label>加密<select name="security"><option value="tls" <?= ($smtp['security']??'tls')==='tls'?'selected':'' ?>>STARTTLS（通常 587）</option><option value="ssl" <?= ($smtp['security']??'tls')==='ssl'?'selected':'' ?>>SSL/TLS（通常 465）</option></select></label><label>用户名<input name="username" value="<?= $e($smtp['username']??'') ?>"></label><label>密码 / 授权码<input name="password" type="password" autocomplete="new-password" placeholder="留空保留已配置密码"></label><label>发件邮箱<input name="from" type="email" value="<?= $e($smtp['from']??'') ?>" required></label><button>保存邮件配置</button></form></article></section><section class="card"><h2>最近 50 条审计记录</h2><div class="table"><table><tr><th>时间（UTC）</th><th>事件</th><th>账号 ID</th><th>说明</th></tr><?php foreach($events as $event): ?><tr><td><?= $e(gmdate('Y-m-d H:i:s',(int)$event['created_at'])) ?></td><td><?= $e($event['event']) ?></td><td><?= $e($event['user_id']??'—') ?></td><td><?= $e($event['detail']) ?></td></tr><?php endforeach ?></table></div></section>